Lemma rdn_ext : forall segs k m1 m2 (a : word),
  (bv_unsigned a + Z.of_nat k <= 2^64)%Z ->
  (forall x : word, (bv_unsigned a <= bv_unsigned x < bv_unsigned a + Z.of_nat k)%Z -> m1 x = m2 x) ->
  rdn segs m1 a k = rdn segs m2 a k.
