  bytes = pre ++ s ++ post -> (j < length s)%nat ->
  (bv_unsigned sp + Z.of_nat (length bytes) < 2^64)%Z ->
  rdn segs (stack_to_mem sp bytes) (sp + nat_to_word (length pre + j)) 1%nat
